/bin/bash -c "python3 - <<'PY'
# Check the role-binding behavior specified in Section 5.1 and Algorithm 1.
roles={'Arg1','Arg2'}
events={'t1':{'Arg1':'A','Arg2':'B'},'t2':{'Arg1':'B','Arg2':'A'}}
mention_labels={}
links=set()
for trigger,args in events.items():
    for role,span in args.items():
        mention_labels.setdefault(span,set()).add(role)
        links.add((trigger,span))
gold={(t,r,s) for t,args in events.items() for r,s in args.items()}
decoded={(t,r,s) for t,s in links for r in mention_labels[s] if r in roles}
print('Gold event-role-argument triples:',sorted(gold))
print('Untyped EAL links:',sorted(links))
print('THL role labels:',{s:sorted(rs) for s,rs in mention_labels.items()})
print('Extra triples produced by Algorithm 1:',sorted(decoded-gold))
PY"
